from pathlib import Path
from PIL import Image,ImageChops,ImageStat
import json,math,os,subprocess
r=Path(os.environ['OUT']);variants=range(4);metrics=['393x852','402x874'];motions=['normal','reduced'];scenes=['initial','carried','partial','full-invalid-left','full-invalid-right','success','timeout'];rows=[];fail=[]
for v in variants:
 for metric in metrics:
  for scene in scenes:
   a=Image.open(r/f'table{v}-{metric}-{scene}-normal.png').convert('RGB');b=Image.open(r/f'table{v}-{metric}-{scene}-reduced.png').convert('RGB');d=ImageChops.difference(a,b);st=ImageStat.Stat(d);rows.append({'key':f'{v}-{metric}-{scene}','size':[a.width,a.height],'mae':round(sum(st.mean)/3,3),'normalizedRMSE':round(math.sqrt(sum(x*x for x in st.rms)/3)/255,6),'changed':round(sum(px!=(0,0,0) for px in d.getdata())/(a.width*a.height),5)})
   for m in motions:
    e=json.loads((r/f'evidence-{v}-{metric}-{scene}-{m}.json').read_text());s=e['state'];ok=(scene!='initial' or all(x=='tray' for x in s['locations'])) and (scene!='carried' or s['carried']==0) and (scene!='partial' or not s['evaluation']['full']) and (scene!='full-invalid-left' or s['evaluation']['full'] and s['evaluation']['missing']==['window']) and (scene!='full-invalid-right' or s['evaluation']['full'] and s['evaluation']['missing']==['shelf']) and (scene!='success' or s['result']=='success' and s['evaluation']['valid']) and (scene!='timeout' or s['result']=='timeout')
    if e['status']!='pass' or e['dpr']!=3 or e['errors'] or e['external'] or e['viewport']['bodyScrollWidth']>e['width'] or min(min(t['height'],t['width']) for t in e['targets'])<44 or not ok:fail.append(f'evidence {v} {metric} {scene} {m}')
