 if len(e['shapes'])>3 or any(c['answer'] or c['correct'] or min(c['rect']['width'],c['rect']['height'])<44 for c in e['cookies']) or any(s['answer'] or s['correct'] or min(s['rect']['width'],s['rect']['height'])<44 for s in e['slots']):fail.append(f'cue {v}')
for v in variants:
 for m in motions:
  e=json.loads((r/f'touch-success-{v}-{m}.json').read_text())
  if not(e['status']=='pass' and e['trace']==e['solution'] and e['after']['result']=='success' and e['after']['evaluation']['valid'] and len(e['finishes'])==1 and e['finishes'][0]['correct'] and not e['overflow'] and not e['errors'] and not e['external']):fail.append(f'touch {v} {m}')
for v,m in [(0,'normal'),(3,'reduced')]:
 e=json.loads((r/f'keyboard-{v}-{m}.json').read_text())
 if not(e['status']=='pass' and e['sawArrow'] and e['after']['result']=='success' and e['after']['evaluation']['valid'] and len(e['finishes'])==1 and e['finishes'][0]['correct'] and not e['overflow'] and not e['errors']):fail.append(f'keyboard {v} {m}')
for m in motions:
 e=json.loads((r/f'correction-{m}.json').read_text())
 if not(e['before']['evaluation']['full'] and not e['before']['evaluation']['valid'] and e['before']['evaluation']['missing']==['window'] and e['after']['result']=='success' and len(e['finishes'])==1 and e['finishes'][0]['correct']):fail.append(f'correction {m}')
for metric,m in [('390x844','normal'),('430x932','reduced')]:
 e=json.loads((r/f'deadline-{metric}-{m}.json').read_text())
